<map version="1.0.1"><node CREATED="1747229426720" ID="ID_root" MODIFIED="1747229426720" TEXT="mmap"><node CREATED="1747229426720" ID="ID_ff99060d215dcd42" POSITION="right" MODIFIED="1747229426720" TEXT="概述"><node CREATED="1747229426720" ID="ID_2d598a833adf258b" MODIFIED="1747229426720" TEXT="是一种内存映射，直接将文件里的内容映射到内存。&amp;nbsp;操作这块内存，就等价于&amp;lt;br&amp;gt;操作这个文件"></node></node><node CREATED="1747229426720" ID="ID_5cc3f01e1764a423" POSITION="right" MODIFIED="1747229426720" TEXT="使用"><node CREATED="1747229426720" ID="ID_7a279f6eeadc4736" MODIFIED="1747229426720" TEXT="mmap"><node CREATED="1747229426720" ID="ID_3c5d841e56441813" MODIFIED="1747229426720" TEXT="#include &amp;lt;sys/mman.h&amp;gt;&amp;lt;br&amp;gt;void *mmap(void *addr, size_t length, int prot, int flags, int fd, off_t offset);"></node><node CREATED="1747229426720" ID="ID_1b719685df1fed21" MODIFIED="1747229426720" TEXT="void *addr:&amp;nbsp;内存从何处开始映射。建议直接写NULL"></node><node CREATED="1747229426720" ID="ID_608312c735dfa596" MODIFIED="1747229426720" TEXT="length/offset:&amp;nbsp;组合决定映射文件的哪块位置进来"></node><node CREATED="1747229426720" ID="ID_ffc4b3b10c1e2d1d" MODIFIED="1747229426720" TEXT="int prot:&amp;nbsp;映射了之后，内存的权限。&amp;nbsp;"><node CREATED="1747229426720" ID="ID_8b0f4837e17cb05e" MODIFIED="1747229426720" TEXT="PROT_READ:&amp;nbsp;读"></node><node CREATED="1747229426720" ID="ID_afd1d84ab46528b5" MODIFIED="1747229426720" TEXT="PROT_WRITE | PROT_READ :&amp;nbsp;可读可写。&amp;nbsp;建议大家一起协商"></node></node><node CREATED="1747229426720" ID="ID_0de902ba61200653" MODIFIED="1747229426720" TEXT="int flags:&amp;nbsp;映射的内存的回写特点。&amp;nbsp;"><node CREATED="1747229426720" ID="ID_303d98ef948be0ef" MODIFIED="1747229426720" TEXT="MAP_SHARED&amp;lt;br&amp;gt;目前直接用它，保证修改完内存直接回写到文件中"></node></node><node CREATED="1747229426720" ID="ID_36bc29cdddbb5482" MODIFIED="1747229426720" TEXT="int fd:&amp;nbsp;打开的文件描述符"></node><node CREATED="1747229426720" ID="ID_3549b4478dfaaeff" MODIFIED="1747229426720" TEXT="建议的参数"><node CREATED="1747229426720" ID="ID_d58bafd297d28a92" MODIFIED="1747229426720" TEXT="addr建议直接NULL"></node><node CREATED="1747229426720" ID="ID_f6a9a23be23a3ac4" MODIFIED="1747229426720" TEXT="prot。如果只读PROT_READ；&amp;nbsp;读写 PROT_READ | PROT_WRITE"></node><node CREATED="1747229426720" ID="ID_10707823780301fd" MODIFIED="1747229426720" TEXT="flags&amp;nbsp;建议直接写 MAP_SHARED"></node></node><node CREATED="1747229426720" ID="ID_60bac59079a45b73" MODIFIED="1747229426720" TEXT="返回值有点特殊"><node CREATED="1747229426720" ID="ID_e820bbd2450f1734" MODIFIED="1747229426720" TEXT="如果成功，会返回指针。操作指针这块区域，就相当于操作文件"></node><node CREATED="1747229426720" ID="ID_aa713e70fd6dd71d" MODIFIED="1747229426720" TEXT="如果失败，返回MAP_FAILED。&amp;nbsp;"></node></node></node><node CREATED="1747229426720" ID="ID_174d13045b0eebc3" MODIFIED="1747229426720" TEXT="munmap"><node CREATED="1747229426720" ID="ID_0e9c742569c17228" MODIFIED="1747229426720" TEXT="传入获取到的void *"></node><node CREATED="1747229426720" ID="ID_11448ec3f60c09ac" MODIFIED="1747229426720" TEXT="length和获取时的保持一致"></node></node></node><node CREATED="1747229426720" ID="ID_f3fd3670978b5516" POSITION="right" MODIFIED="1747229426720" TEXT="一些坑"><node CREATED="1747229426720" ID="ID_4bb9a295aafb8a5a" MODIFIED="1747229426720" TEXT="offset的取值问题"><node CREATED="1747229426720" ID="ID_3244309a0126025f" MODIFIED="1747229426720" TEXT="offset的取值，只能是4096的倍数。如果是其他值，这里会直接报错"></node></node><node CREATED="1747229426720" ID="ID_dea41e80160ca6a6" MODIFIED="1747229426720" TEXT="总线错误"><node CREATED="1747229426720" ID="ID_6212002d3f08c4b7" MODIFIED="1747229426720" TEXT="如果在mmap中，要访问的文件大小为0，但是却想映射几个字节，这时候就可能出现总线错误&amp;lt;br&amp;gt;"></node><node CREATED="1747229426720" ID="ID_e7d77050bf168ea9" MODIFIED="1747229426720" TEXT="如果要映射的数目，大于了文件的实际大小。&amp;nbsp;这时候访问超出的部分，也可能出现"></node></node><node CREATED="1747229426720" ID="ID_2185af85be0d6658" MODIFIED="1747229426720" TEXT="open的flag和mmap的prot"><node CREATED="1747229426720" ID="ID_181c4eec7e8b541c" MODIFIED="1747229426720" TEXT="如果只是想读数据，&amp;nbsp;这时候open用&amp;nbsp;O_RDONLY，mmap用PROT_READ"></node><node CREATED="1747229426720" ID="ID_7227516b2866795a" MODIFIED="1747229426720" TEXT="如果想写数据，这时候open&amp;nbsp;用O_RDWR， mmap用 PROT_READ|PROT_WRITE"></node></node></node><node CREATED="1747229426720" ID="ID_3527827da5515ef8" POSITION="right" MODIFIED="1747229426720" TEXT="fread&amp;amp;read&amp;amp;mmap对比"><node CREATED="1747229426720" ID="ID_c4a5e41d70b954f8" MODIFIED="1747229426720" TEXT="fread&amp;nbsp; 有缓冲文件流。用来读文件的&amp;lt;br&amp;gt;&amp;lt;br&amp;gt;read&amp;nbsp; 无缓冲文件流。读文件的。&amp;lt;br&amp;gt;&amp;lt;br&amp;gt;mmap&amp;nbsp; 文件映射。 &amp;lt;br&amp;gt;&amp;lt;br&amp;gt;如果说是操作普通文件， fread和read都可以。 read要注意一下读的数组大点。&amp;lt;br&amp;gt;后续，在Linux下开发， read和write，可能出现的会更多。 &amp;lt;br&amp;gt;如果说要做大文件的复制。 这时候可以考虑使用mmap来提高效率。 &amp;lt;br&amp;gt;&amp;lt;br&amp;gt;理论上， read比fread少一次数据拷贝； mmap比read少一次数据拷贝。&amp;nbsp;&amp;lt;br&amp;gt;"></node><node CREATED="1747229426720" ID="ID_34a9788f249976e3" MODIFIED="1747229426720" TEXT="数据复制了几次，要知道。&amp;nbsp;&amp;lt;br&amp;gt;有缓冲区文件流，拷了两次数据。&amp;nbsp;一次是从内核到用户态缓冲区，一次是用户态缓冲区到自己的数组。&amp;nbsp;&amp;lt;br&amp;gt;无缓冲区文件流，拷了一次数据。&amp;nbsp;从内核到自己的数组。&amp;nbsp;&amp;lt;br&amp;gt;mmap，没有拷贝数据。&amp;nbsp;我们拿到的指针，是内核开的后门。"></node></node><node CREATED="1747229426720" ID="ID_b7d850a0ec699dc7" POSITION="right" MODIFIED="1747229426720" TEXT="案例"><node CREATED="1747229426720" ID="ID_6ca653df5eed2c5e" MODIFIED="1747229426720" TEXT="小写转大写"><node CREATED="1747229426720" ID="ID_e2379c086b10b6a0" MODIFIED="1747229426720" TEXT="将文件中的小写字母，转成大写字母，其他的不动"></node><node CREATED="1747229426720" ID="ID_714c31aca92e1aef" MODIFIED="1747229426720" TEXT="思路就是利用mmap将数据映射进来，挨个检查，是小写，就转成大写。&amp;nbsp;再放回原本的位置上&amp;lt;br&amp;gt;"></node><node CREATED="1747229426720" ID="ID_a0c24e086c8c9500" MODIFIED="1747229426720" TEXT="在这个过程中，我们发现mmap的时候。&amp;nbsp;要传length。这时候&amp;lt;br&amp;gt;学会另一个系统调用 fstat"><node CREATED="1747229426720" ID="ID_ddca5ef9d32b815b" MODIFIED="1747229426720" TEXT="其他的参数一模一样，之前之前stat传path。现在传fd"></node><node CREATED="1747229426720" ID="ID_4963a5a5ab0eccca" MODIFIED="1747229426720" TEXT="可以从buf里面，拿到st_size&amp;nbsp;就是大小"></node></node><node CREATED="1747229426720" ID="ID_4758332ed9763292" MODIFIED="1747229426720" TEXT="如果使用read/write函数"><node CREATED="1747229426720" ID="ID_fec8bc27fc0f042b" MODIFIED="1747229426720" TEXT="要注意一下，读取了之后，指针会往后挪。&amp;nbsp;所以有一个和fseek类似的函数， lseek&amp;lt;br&amp;gt;大家晚上可以练习一下"></node></node></node><node CREATED="1747229426720" ID="ID_991bfe38fc4c4d0c" MODIFIED="1747229426720" TEXT="大文件的复制"><node CREATED="1747229426720" ID="ID_a2dadc2be55cfbbb" MODIFIED="1747229426720" TEXT="就意味着文件很大，我们无法一次弄进来。&amp;nbsp;"></node><node CREATED="1747229426720" ID="ID_e59d0f1cb4037ccb" MODIFIED="1747229426720" TEXT="如果是使用read/write.其实无所谓，弄个循环使劲循环就完了。&amp;lt;br&amp;gt;但是对于mmap，这种思路不行"><node CREATED="1747229426720" ID="ID_997146af12ad7770" MODIFIED="1747229426720" TEXT="首先，先将文件大小获取到。 100M&amp;nbsp;&amp;lt;br&amp;gt;一次获取一点进来。 4M. len+offset&amp;nbsp;"></node></node><node CREATED="1747229426720" ID="ID_773e3d9e2ab348c6" MODIFIED="1747229426720" TEXT="思路"><node CREATED="1747229426720" ID="ID_42e25a1a80108945" MODIFIED="1747229426720" TEXT="既然不能一把整进来。这时候一点点弄进来。&amp;lt;br&amp;gt;这时候要手动存储，已经读取的大小。以及偏移量各种信息，需要自己来处理"></node><node CREATED="1747229426720" ID="ID_3ed3a2fc099b357a" MODIFIED="1747229426720" TEXT="length和offset"><node CREATED="1747229426720" ID="ID_d4560477585c5fb7" MODIFIED="1747229426720" TEXT="offset一定要是4K的倍数"></node></node><node CREATED="1747229426720" ID="ID_8e52cb1ca84e43d3" MODIFIED="1747229426720" TEXT="在这次复制中，copied_size，&amp;nbsp;"></node></node></node></node></node></map>